#resolveSafePath(relativePath) {
  const resolved = path.resolve(this.workspaceRoot, relativePath);
  if (!resolved.startsWith(this.workspaceRoot + path.sep)) {
    throw new Error('VIOLAÇÃO DE SANDBOX: O caminho escapa do workspace permitido.');
  }
  if (path.basename(resolved).startsWith('.env')) {
    throw new Error('ACESSO NEGADO: Arquivos .env são bloqueados.');
  }
  return resolved;
}
